window.TRYCKTRACK_QUESTION_BANK = (window.TRYCKTRACK_QUESTION_BANK || []).concat([{"id":"obstetricia-inep-001","number":1,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281697","stem":"Gestante, 33 anos, G2 P1 A0, cesariana há 3 anos por apresentação pélvica, fez pré-natal de baixo risco. Admitida na maternidade em trabalho de parto espontâneo, com apresentação cefálica, bolsa rota há 1 hora, com líquido amniótico claro e 6 cm de dilatação. Evoluiu de forma satisfatória sob monitorização fetal. Após 2 horas de evolução do trabalho de parto, passa a apresentar dor abdominal súbita, contínua e associada a mal-estar intenso e sangramento vaginal moderado. Ao exame: PA 82 x 42 mmHg; FC 134 bpm; FR 28 irpm; temperatura axilar 36,6 °C; pele pálida, fria e sudoreica. Útero doloroso, mal definido e com partes fetais facilmente palpáveis; BCF 80 bpm sustentado; dilatação de 8 cm, plano -2 de De Lee, sangramento ativo e elevação da apresentação fetal. Diante desse quadro, qual deve ser a conduta imediata?","options":{"A":"Aguardar progressão do parto, considerando a dilatação cervical avançada.","B":"Solicitar ultrassonografia obstétrica antes de definir a via de parto.","C":"Aplicar fórceps de alívio para abreviar o parto vaginal.","D":"Realizar cesariana em caráter de emergência."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-002","number":2,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281692","stem":"Uma gestante de 30 anos, vivendo com HIV, em uso regular de terapia antirretroviral desde o 1º trimestre, apresenta carga viral indetectável no 3º trimestre da gestação. Manifesta dúvidas quanto ao risco de transmissão vertical e às condutas no parto, e questiona sobre a possibilidade de amamentar. Considerando as diretrizes do Ministério da Saúde, qual é a explicação mais adequada para essa paciente?","options":{"A":"A manutenção da terapia antirretroviral com carga viral indetectável reduz o risco de transmissão vertical; a via de parto seguirá critérios obstétricos e de carga viral; a amamentação é contraindicada, garantindo-se acesso à fórmula infantil.","B":"Apesar da carga viral indetectável, o risco de transmissão vertical permanece elevado; indica-se cesariana eletiva; a amamentação é contraindicada e indica-se a fórmula infantil.","C":"Com a manutenção da terapia antirretroviral e da carga viral indetectável, o risco de transmissão vertical é baixo; a assistência obstétrica indicada deve priorizar parto vaginal e a amamentação é autorizada mediante acompanhamento rigoroso.","D":"A redução do risco de transmissão vertical depende da manutenção da terapia antirretroviral e da carga viral indetectável; a escolha da via de parto deve seguir a indicação obstétrica e a amamentação pode ser indicada se for o desejo da paciente."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-003","number":3,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281682","stem":"Puérpera, 24 anos, imigrante recém-chegada ao Brasil, é admitida na maternidade 30 minutos após parto extra-hospitalar. Relata que o parto ocorreu rapidamente, sendo a placenta completamente expulsa alguns minutos após. Ao exame inicial, apresenta-se hemodinamicamente estável e com útero contraído, apesar de manter sangramento vaginal moderado. Ao exame do canal de parto, identifica-se laceração perineal envolvendo pele, mucosa vaginal e musculatura perineal, sem acometimento do esfíncter anal ou da mucosa retal. A paciente demonstra ansiedade, dificuldade de compreensão do idioma e questiona repetidamente o que será feito. Considerando a avaliação realizada e as boas práticas recomendadas pela OMS e pelo Ministério da Saúde para uma assistência humanizada, a conduta adequada é","options":{"A":"expectante, evitando sutura perineal para não aumentar a ansiedade da puérpera, com orientações gerais e observação clínica.","B":"suturar a laceração perineal para controle do sangramento, priorizando o procedimento primeiro e, após, as orientações, pela gravidade do caso.","C":"explicar o diagnóstico e o procedimento em linguagem acessível, buscando consentimento da puérpera, e suturar a laceração com anestesia local.","D":"encaminhar ao centro cirúrgico para reparo sob anestesia geral, reduzindo a exposição da paciente e a dificuldade de comunicação."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-004","number":4,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281675","stem":"Primigesta de 28 anos com idade gestacional de 41 semanas foi admitida para assistência ao trabalho de parto espontâneo. Negou comorbidades e não apresentou intercorrências durante o pré-natal. Oito horas após a admissão, evoluiu para período expulsivo, em posição de litotomia. Porém, após a exteriorização da cabeça, esta retraiu-se contra o períneo e não houve o desprendimento fetal. Diante deste quadro, qual deve ser a conduta inicial do médico?","options":{"A":"Reposicionar a paciente promovendo hiperflexão das pernas e das coxas.","B":"Realizar tração forte e contínua no polo cefálico e pressão no fundo uterino.","C":"Introduzir a mão pelo vazio sacral e promover a adução do ombro anterior.","D":"Realizar episiotomia médio-lateral ampla."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-005","number":5,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281668","stem":"Gestante, 37 anos, G3 P2 A0, foi admitida na maternidade para interrupção eletiva da gravidez com idade gestacional de 37 semanas devido à bolsa rota. Realizou todas as consultas e exames pré-natais, conforme estabelecido nos protocolos, e não apresentou nenhuma outra alteração. Os dois partos vaginais anteriores não tiveram intercorrências. Ao exame, peso 93 kg; altura 1,60 m; PA 110 x 70 mmHg, altura uterina 33 cm, BCF 140 bpm; ausência de sangramento vaginal. Com base na estratificação de risco recomendada pelo Ministério da Saúde, essa paciente apresenta qual fator de risco para hemorragia pós-parto?","options":{"A":"Idade > 35 anos.","B":"Dois partos vaginais prévios.","C":"Bolsa rota.","D":"IMC > 35 kg/m²."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-006","number":6,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281667","stem":"Mulher, 22 anos, gestante de 8 semanas, realiza teste rápido para sífilis na Unidade Básica de Saúde, com resultado reagente. Nega sintomas ou lesões genitais e demonstra preocupação sobre como informar ao parceiro, com quem mantém relacionamento estável há cerca de 1 ano. Relata relações sexuais atuais com outras parcerias e questiona a necessidade de tratá-las. Além do aconselhamento pós-teste, qual é o manejo adequado para a essa situação?","options":{"A":"Tratar a gestante e entregar a prescrição das parcerias, as quais serão comunicadas do diagnóstico por ela.","B":"Tratar a gestante e oferecer apoio à convocação das parcerias para iniciar o tratamento.","C":"Solicitar VDRL da gestante para confirmação do diagnóstico e oferecer apoio à convocação das parcerias para avaliação diagnóstica.","D":"Solicitar FTA-Abs da gestante e das parcerias para a confirmação do diagnóstico."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-007","number":7,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281661","stem":"Primigesta de 24 anos, sem comorbidades ou intercorrências gestacionais, foi admitida com idade gestacional de 41 semanas em maternidade de baixo risco para assistência ao trabalho de parto espontâneo. A evolução do trabalho de parto está registrada no partograma a seguir: Após a última avaliação, a paciente e seu marido demonstram preocupação, pois imaginavam que o trabalho de parto avançaria mais rapidamente, e solicitam orientações sobre a necessidade de intervenções. Considerando as recomendações preconizadas pelo Ministério da Saúde, a melhor conduta nesse caso é","options":{"A":"realizar amniotomia.","B":"administrar ocitocina.","C":"indicar cesárea.","D":"manter observação."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-008","number":8,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281654","stem":"Gestante de 30 anos, G2 P1, com 28 semanas de gestação, comparece à Unidade Básica de Saúde para consulta de rotina. Nega disúria, urgência miccional, dor suprapúbica, lombar, febre ou comorbidades. Traz exames solicitados da rotina pré- natal, cujos resultados são apresentados a seguir: Qual é a interpretação para os exames laboratoriais e o manejo adequado da paciente?","options":{"A":"Diagnosticar bacteriúria assintomática e iniciar tratamento imediato.","B":"Considerar o exame contaminado e repetir a urocultura com nova coleta.","C":"Diagnosticar cistite aguda subclínica e iniciar antibiótico.","D":"Considerar o resultado da urocultura alterado e acompanhar a gestação."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-009","number":9,"area":"Obstetrícia","source":"INEP","sourceCode":"4000281637","stem":"Mulher, 30 anos, chega à Unidade de Pronto Atendimento com relato de dor pélvica de intensidade 8/10, além de náuseas e vômitos. Relata ciclos menstruais regulares a cada 28 dias, com DUM há 35 dias. Tem vida sexual ativa e usa DIU como método contraceptivo. Nega patologias e uso de medicações. Ao exame abdominal, apresenta descompressão brusca dolorosa em andar inferior do abdome. No exame ginecológico, identificam-se conteúdo vaginal sanguinolento, útero em AVF amolecido e dor em fundo de saco posterior. Os anexos são impalpáveis. Para o diagnóstico mais provável da condição dessa paciente, quais exames devem ser solicitados?","options":{"A":"Hemograma e radiografia de abdome.","B":"Beta HCG e Proteína C Reativa.","C":"Hemograma e ultrassonografia abdominal.","D":"Beta HCG e ultrassonografia transvaginal."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-010","number":10,"area":"Obstetrícia","source":"INEP","sourceCode":"4000282607","stem":"Multípara, 37 semanas, obesa, apresentando diabetes mellitus gestacional controlada com insulina NPH e regular. Evoluiu para parto normal, e o recém-nascido pesou 3.300 g. A conduta no puerpério imediato deve ser","options":{"A":"suspender insulinoterapia.","B":"iniciar hipoglicemiante oral.","C":"manter insulina NPH em 1/3 da dose da gravidez.","D":"manter insulinoterapia com a dosagem do pré-natal."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-011","number":11,"area":"Obstetrícia","source":"INEP","sourceCode":"4000282600","stem":"Paciente G5P3C1, 35 anos, idade gestacional de 15 semanas por ecografia relizada com 8 semanas, hipertensa crônica em uso de enalapril, antecedente de pré-eclâmpsia. Comparece à consulta de pré-natal na Unidade Básica de Saúde (UBS) com pressão arterial de 140 x 90 mmHg. Qual é a conduta medicamentosa indicada para essa paciente?","options":{"A":"Captopril, varfarina e ácido acetilsalicílico.","B":"Furosemida, varfarina e carbonato de cálcio.","C":"Losartana, enoxaparina e carbonato de cálcio.","D":"Alfa-metildopa, ácido acetilsalicílico e carbonato de cálcio."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-012","number":12,"area":"Obstetrícia","source":"INEP","sourceCode":"4000282593","stem":"Primigesta de 29 anos, com 41 semanas de gestação e pré-natal de risco habitual, comparece à Unidade Básica de Saúde (UBS) para consulta de rotina. Ela está preocupada com a duração da gravidez e deseja saber quais serão o s próximos passos. A paciente está assintomática, relata movimentação fetal presente, e o exame físico está normal para a idade gestacional. Perfil biofísico fetal realizado há 1 dia encontra-se dentro da normalidade. Considerando o quadro clínico apresentado e a idade gestacional, a conduta é","options":{"A":"orientar repouso domiciliar, com planejamento da indução do parto após 42 semanas.","B":"solicitar dopplervelocimetria obstétrica para avaliar o bem- estar fetal e planejar o manejo com base no resultado.","C":"realizar amnioscopia para verificar a presença de mecônio no líquido amniótico e planejar o manejo com base no resultado.","D":"solicitar perfil biofísico fetal e cardiotocografia a cada 2 a 3 dias e planejamento da indução do parto até 41 semanas e 6 dias."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-013","number":13,"area":"Obstetrícia","source":"INEP","sourceCode":"4000282588","stem":"Parturiente de 29 anos, sem comorbidades, esteve em trabalho de parto por 8 horas e evoluiu para parto vaginal. Após 10 minutos do desprendimento do feto, ainda não se observou a expulsão da placenta. A paciente está estável e sem sinais de hemorragia. Diante do quadro apresentado, a conduta a ser adotada é","options":{"A":"aguardar a expulsão espontânea da placenta, sem intervenções adicionais, e observar sinais de separação.","B":"realizar tração controlada do cordão umbilical, enquanto se estabiliza o útero com a mão suprapúbica.","C":"iniciar curagem placentária, devido ao tempo transcorrido sem desprendimento placentário.","D":"administrar uterotônico adicional e realizar massagem uterina para auxiliar a dequitação."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-014","number":14,"area":"Obstetrícia","source":"INEP","sourceCode":"4000258833","stem":"Paciente primigesta, com 14 semanas de gestação, chega à urgência apresentando sangramento vaginal leve há 1 dia, sem dor abdominal. Apresenta tipo sanguíneo “O” Rh negativo, com coombs indireto negativo, não é possível saber o tipo sanguíneo do genitor. Durante o exame, não é detectado sinal de instabilidade hemodinâmica. Após avaliação inicial, a ultrassonografia transvaginal revela presença de embrião vivo e hematoma subcoriônico. Qual é a conduta mais adequada para essa paciente?","options":{"A":"Informar que não há indicação de medidas adicionais.","B":"Administrar imunoglobulina anti-D e reavaliar em 7 a 14 dias.","C":"Indicar repouso relativo e prescrever progesterona micronizada.","D":"Indicar repouso relativo e aguardar 72 horas para administrar imunoglobulina."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-015","number":15,"area":"Obstetrícia","source":"INEP","sourceCode":"4000258828","stem":"Paciente de 28 anos, primigesta, teve infecção por Zika vírus com 12 semanas de gestação. A ultrassonografia morfológica, realizada com 23 semanas, revelou microcefalia, redução do diâmetro biparietal, leve aumento dos ventrículos laterais, calcificações subcorticais, redução do volume cerebral e lisencefalia. Diante desse resultado, a paciente ficou apreensiva e solicitou interrupção da gestação. De acordo com o ordenamento jurídico brasileiro, qual é a conduta adequada nesse caso?","options":{"A":"O procedimento poderá ser feito, mediante solicitação por escrito da gestante.","B":"O procedimento não poderá ser realizado, independentemente da idade gestacional.","C":"O procedimento não poderá ser realizado, por já ter ultrapassado 20 semanas de gestação.","D":"O procedimento poderá ser realizado, após a confirmação do diagnóstico por dois especialistas em medicina fetal."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-016","number":16,"area":"Obstetrícia","source":"INEP","sourceCode":"4000258800","stem":"Paciente de 30 anos, 3 cesarianas anteriores, com pré-natal atual de risco habitual. Foi submetida a parto cesáreo eletivo com 39 semanas de gestação. O procedimento cirúrgico aconteceu sem intercorrências. Vinte minutos após o término da cirurgia, queixa-se de mal-estar e tontura. Exame físico: palidez; frequência cardíaca de 110 bpm; pressão arterial de 90 x 55 mmHg. Útero amolecido, 4 cm acima da cicatriz umbilical. Curativo limpo e seco. Sangramento vaginal e m grande quantidade, ultrapassando o forro vaginal. Foi realizado acesso venoso calibroso, solicitado hemograma e tipagem sanguínea com reserva de hemocomponentes. Em relação ao quadro clínico da paciente, qual deve ser a próxima conduta?","options":{"A":"Histerectomia abdominal subtotal.","B":"Laparotomia com sutura de B Lynch.","C":"Massagem uterina bimanual e uterotônicos.","D":"Tamponamento uterino e reposição volêmica."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-017","number":17,"area":"Obstetrícia","source":"INEP","sourceCode":"4000258793","stem":"Paciente, 20 semanas de gestação, comparece à consulta de pré-natal, com exame de sorologia para toxoplasmose (Elisa): IgM positiva e IgG negativa. Quanto ao caso citado, deve-se","options":{"A":"iniciar espiramicina e manter até o parto","B":"iniciar espiramicina e repetir as sorologias em 14 dias.","C":"solicitar o teste de avidez de IgG para o Toxoplasma gondii.","D":"iniciar tratamento tríplice – sulfadiazina, pirimetamina e ácido folínico."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-018","number":18,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240454","stem":"Primigesta de 25 anos procura o pronto atendimento de ginecologia e obstetrícia com história de atraso menstrual e resultado de beta-hCG quantitativo de 10.000 mlU/mL realizado há 2 dias. Não se recorda da data da última menstruação. Queixa-se de sangramento vaginal, em pequena quantidade, que já dura 3 dias. Ao exame especular, nota-se presença de sangramento vivo em pequena quantidade e, ao toque, percebe-se colo uterino fechado. Solicitado beta-hCG no dia da consulta, com resultado de 23.400 mlU/mL. A partir desses dados, assinale a alternativa que apresenta, respectivamente, o diagnóstico desse caso e a conduta adequada.","options":{"A":"Gestação ectópica; laparotomia.","B":"Ameaça de aborto; repouso relativo.","C":"Aborto incompleto; curetagem uterina.","D":"Aborto em evolução; acompanhamento clínico"},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-019","number":19,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240449","stem":"Gestante de 39 anos, G4P3, 12 semanas de gestação, comparece à primeira consulta de pré-natal na atenção primária. A paciente é hipertensa crônica há 2 anos, faz uso de losartana e apresenta índice de massa corporal (IMC) de 35 kg/m², encontra-se assintomática. Considerando esse contexto, assinale a conduta inicial e a avaliação a ser realizada.","options":{"A":"Suspender losartana e iniciar metildopa e AAS; realizar pesquisa de lesão de órgãos-alvo.","B":"Manter losartana e iniciar AAS; solicitar exames para avaliar a função hepática.","C":"Suspender losartana; indicar avaliação cardiológica detalhada.","D":"Manter losartana; realizar pesquisa de hipertensão secundária."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-020","number":20,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240448","stem":"Mulher de 34 anos, com 4 filhos, desempregada, comparece a uma unidade básica de saúde (UBS) com queixa de atraso menstrual de um mês. Durante a consulta, a paciente relata que está muito aflita, por ter realizado um teste de gravidez cujo resultado foi positivo. A;rma que compareceu à consulta porque não deseja essa gravidez. Quando questionada, a paciente nega qualquer situação de violência sexual. Nesse caso, além de acolher e acalmar a paciente, a melhor abordagem a ser realizada pelo médico deve ser","options":{"A":"iniciar o pré-natal regular, mencionando a possibilidade de entrega voluntária da criança para adoção após seu nascimento.","B":"desencorajar a realização de um aborto, apesar da paciente ter direito, enfatizando os riscos à saúde advindos do procedimento de abortamento, como hemorragia, infecção, perfuração uterina, infertilidade e morte.","C":"assegurar o direito às informações clínicas e legais adequadas, garantir o sigilo e informar sobre sintomas que justifiquem a busca de atendimento médico em caso de realização de um aborto inseguro.","D":"questionar abertamente sobre a intenção de abortar, sem julgamento, e informá-la que tem obrigação ética de fazer um boletim de ocorrência caso o aborto venha a ser realizado."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-021","number":21,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240439","stem":"Gestante de 25 anos é atendida em uma maternidade no primeiro estágio da fase ativa de trabalho de parto. Seu pré-natal foi de risco habitual e ela está com 40 semanas de gestação. Durante a ausculta intermitente, é detectada uma frequência cardíaca fetal mantida de 100 bpm. Diante disso, é realizada cardiotocografia, que mostra parâmetros normais, exceto a linha de base em torno de 102 bpm por um período de 10 minutos. A paciente não apresenta outros sinais ou sintomas de complicações, e o restante do exame físico está dentro dos parâmetros esperados para a fase ativa do trabalho de parto. Diante desse quadro clínico, a conduta adequada é","options":{"A":"encaminhar a paciente para cesariana por se tratar de sofrimento fetal agudo.","B":"administrar ocitocina e acelerar a ultimação do parto por se tratar de sofrimento fetal agudo.","C":"iniciar tocolíticos para reduzir a atividade uterina e aguardar melhora espontânea da frequência cardíaca fetal.","D":"administrar oxigênio e mudar a posição da gestante, reavaliando a frequência cardíaca fetal após alguns minutos"},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-022","number":22,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240434","stem":"Mulher, G2P1 (parto vaginal), é conduzida ao serviço de urgência obstétrica por estar desacordada, após ter apresentado dor abdominal súbita e desmaio em casa. Está com 35 semanas de gestação e é hipertensa crônica em uso de metildopa e nifedipina. Está inconsciente, apresenta tônus uterino aumentado, com batimento cardíaco fetal de 50 bpm, colo uterino fechado e com moderado sangramento escuro por via vaginal. Ela apresenta os seguintes dados vitais: Diante desse quadro clínico, assinale a alternativa que apresenta, respectivamente, o diagnóstico e a conduta adequados.","options":{"A":"Descolamento prematuro de placenta; priorizar a estabilização hemodinâmica com reposição volêmica, posicionar a paciente em decúbito lateral e realizar a cesárea imediatamente.","B":"Descolamento prematuro de placenta; iniciar a administração de reposição volêmica com cristaloides e com oxigênio e iniciar a monitorização contínua maternofetal, enquanto a paciente é preparada para o parto vaginal induzido.","C":"Placenta prévia; iniciar a reanimação materna com cristaloides, oxigênio suplementar e administração de uterolíticos para diminuir o tônus e conter o sangramento, enquanto a paciente é transferida para o centro cirúrgico a fim de realizar avaliação de cesariana de urgência.","D":"Placenta prévia; realizar manobras de suporte à vida materna, como reposição volêmica com cristaloides e administração de oxigênio, e iniciar monitorização contínua materno-fetal enquanto a paciente é preparada para o parto vaginal induzido."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-023","number":23,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240429","stem":"Primigesta de 24 anos chega à maternidade com queixa de cefaleia, febre e dores articulares leves há 5 dias. Relata que ontem houve piora da febre e surgimento de manchas pelo corpo, o que a fez procurar a emergência. O obstetra verifica o cartão do pré-natal e constata que ela está com 22 semanas de gestação e já realizou 3 consultas na unidade básica de saúde (UBS), sempre com sinais vitais normais e exames laboratoriais sem alterações. Ao exame físico, a paciente apresenta-se em bom estado geral, lúcida e orientada. Durante a análise clínica, foram obtidos os seguintes resultados: Após ouvir a história da paciente e examiná-la, o médico solicita um hemograma, cujo resultado é: Nesse caso, qual a principal hipótese diagnóstica e a conduta a ser adotada pelo obstetra?","options":{"A":"Dengue; internar imediatamente a paciente, iniciar hidratação venosa, dipirona endovenosa e realizar controle diário de plaquetas.","B":"Chikungunya; colocar a paciente em leito de observação clínica, iniciar hidratação venosa, dipirona e, após terminar, liberar retorno ao pré-natal.","C":"Zika; colocar a paciente em leito de observação clínica, iniciar hidratação venosa, dipirona endovenosa e realizar controle diário de plaquetas.","D":"Febre de Oropouche; internar imediatamente a paciente, iniciar transfusão de plaquetas, paracetamol por via oral e, após a transfusão, liberar retorno ao pré-natal."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-024","number":24,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240414","stem":"Paciente, G3P1A, gestação de 13 semanas, datada pela ecografia de 8 semanas, procura atendimento com queixa de sangramento vaginal há 3 dias, em pequena quantidade. A tipagem sanguínea anotada em seu cartão de pré-natal é A negativo. Ela desconhece a tipagem sanguínea de seu companheiro. Ao exame ginecológico, nota-se sangramento vaginal em moderada quantidade e colo uterino fechado. Solicitado teste de coombs indireto, com resultado positivo. Diante desse contexto, a conduta médica adequada é","options":{"A":"alertar a paciente sobre a inviabilidade da gestação.","B":"realizar imunoglobulina anti-RH, por via endovenosa, imediatamente.","C":"repetir o exame de coombs indireto e solicitar tipagem sanguínea do parceiro.","D":"encaminhar ao pré-natal de alto risco e indicar monitoramento por aloimunização."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-025","number":25,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240394","stem":"Primigesta com idade gestacional de 38 semanas procura a maternidade. Realizou pré-natal regular e todos os seus exames estão dentro da normalidade. Relata sentir ansiedade porque a data provável do parto se aproxima e ela ainda não tem sinais do início do trabalho de parto. Diante disso, expressa desejo de realizar uma cesariana para evitar possíveis complicações. Ao exame clínico, não foram identificadas alterações. Nesse caso, a conduta mais adequada é","options":{"A":"conversar sobre os riscos da cesariana e, caso a paciente mantenha o desejo de realizá-la, agendar o procedimento a partir de 39 semanas de gestação.","B":"expor que, devido aos maiores riscos da cesariana, o parto vaginal é a via de parto indicada em gestações de baixo risco e que, por isso, é inviável optar pela cesariana.","C":"explicar que, em gestações de baixo risco, a cesariana por desejo materno só pode ser realizada antes do início do trabalho de parto, a partir de 41 semanas de gestação.","D":"orientar sobre os riscos da cesariana e, caso a paciente mantenha o desejo de realizá-la, fazer o procedimento imediatamente, posto que a autonomia da gestante deve ser garantida."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-026","number":26,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240389","stem":"Secundigesta com idade gestacional de 18 semanas comparece à consulta na unidade básica de saúde (UBS) para iniciar seu pré-natal. Está assintomática e, ao exame clínico, não são identificadas alterações. A paciente, no entanto, relata que entrou em trabalho de parto espontâneo com 32 semanas em sua primeira gestação. Considerado o caso descrito, é indicado prescrever","options":{"A":"indometacina por via oral diariamente.","B":"pessário vaginal, após 22 semanas de gestação.","C":"progesterona por via intramuscular semanalmente.","D":"progesterona natural micronizada por via vaginal diariamente."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-027","number":27,"area":"Obstetrícia","source":"INEP","sourceCode":"4000240374","stem":"Paciente de 27 anos, G1P0, comparece à unidade de pronto atendimento apresentando dor pélvica leve e sangramento vaginal discreto há 6 horas. Refere data da última menstruação (DUM) há 7 semanas. Ao exame físico, tem-se sinais vitais normais e exame abdominal normal. Ao exame especular, nota-se sangramento em pequena quantidade, vivo, oriundo do orifício externo do colo uterino. Títulos de beta-hCG realizados há dois dias eram de 2.500 mUI/mL. Títulos de beta-hCG realizados no pronto-socorro são de 3.500 mUI/mL. Foi solicitada ultrassonografia transvaginal, que demonstrou ausência de saco gestacional intrauterino e presença de massa anexial à direita, medindo 3 cm, contendo no seu interior imagem compatível com embrião, sem batimentos cardíacos. Com base no quadro clínico e nos achados dos exames complementares, a conduta mais adequada a ser realizada nessa paciente é","options":{"A":"laparoscopia imediata, considerando os níveis em ascenção de beta-hCG e o tamanho da massa anexial.","B":"tratamento com metotrexato intramuscular, considerando os níveis de beta-hCG e o tamanho da massa anexial.","C":"laparotomia imediata, considerando os níveis em ascenção do beta-hCG e a presença de embrião na massa anexial.","D":"monitoramento com ultrassonografia transvaginal e beta-hCG em 48 horas, considerando os níveis em ascenção de beta-hCG."},"answer":"B","explanation":"","needsVisualReview":true},{"id":"obstetricia-inep-028","number":28,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223973","stem":"Um médico de uma unidade básica de saúde realiza consulta pré-natal em gestante com idade gestacional de 30 semanas. Ao realizar o terceiro tempo da manobra de Leopold, na região suprapúbica, identifica estrutura fetal óssea arredondada, regular e compatível com calota craniana. Nesse caso, é correto afirmar que a situação e a apresentação fetais são, respectivamente,","options":{"A":"transversal e cefálica.","B":"longitudinal e pélvica.","C":"transversal e córmica.","D":"longitudinal e cefálica."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-029","number":29,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223958","stem":"Uma paciente multigesta de 40 anos, cardiopata, com idade gestacional de 39 semanas, está na maternidade, em trabalho de parto ativo, sendo assistida pela obstetra. Durante a evolução do parto, a paciente começa a demonstrar exaustão e ausência de forças para a finalização do expulsivo. A obstetra, então, decide aplicar um fórceps de alívio após a analgesia. Para a realização desse procedimento, é necessário constatar a","options":{"A":"presença de concepto vivo.","B":"dilatação cervical de, pelo menos, 8 cm.","C":"integridade das membranas amnióticas.","D":"apresentação fetal no plano -1 de DELEE."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-030","number":30,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223948","stem":"Uma primigesta de 17 anos, com idade gestacional de 35semanas, comparece a pré-natal com queixa de náuseas e relato de vômitos, em média, 4 vezes por dia. Ao exame físico, é identificado que a altura do fundo uterino está 3 cm menor que o esperado para a idade gestacional. O médico orienta exame de ecografia obstétrica devido à suspeita de restrição de crescimento fetal. Considerando-se os parâmetros ecográficos que podem ser utilizados para avaliar essa condição, assinale a alternativa correta.","options":{"A":"O diâmetro biparietal fetal é a medida isolada de maior sensibilidade para esse diagnóstico; o estudo com Doppler só será necessário se comprovada a restrição de crescimento abaixo do percentil 3.","B":"A circunferência abdominal fetal é a medida isolada de maior sensibilidade para esse diagnóstico; o estudo com Doppler permitirá avaliar a circulação materna, a circulação feto-placentária e a circulação fetal.","C":"A circunferência abdominal fetal dividida pelo comprimento do fêmur fetal é o parâmetro de maior sensibilidade para esse diagnóstico; o estudo com Doppler reduz a prematuridade iatrogênica e a mortalidade perinatal.","D":"Todos os parâmetros para mensuração do peso fetal são igualmente sensíveis para esse diagnóstico; o estudo com Doppler permitirá avaliar apenas a artéria cerebral média, a aorta abdominal, o ducto venoso e o seio venoso transverso."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-031","number":31,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223938","stem":"Uma paciente de 39 anos, G2 PV1, com idade gestacional de 40 semanas (calculada por ecografia obstétrica de 10 semanas de idade gestacional), procura sua maternidade de referência. Ela refere movimentação fetal e nega perdas de líquido ou sangramento vaginal. Está em uso de metildopa 750 mg/dia, por hipertensão gestacional, com bom controle pressórico. A paciente tem fator ABO Rh: A+ e realizou todas as rotinas laboratoriais do pré-natal, as quais estavam normais. Sua última ecografia obstétrica com Doppler foi realizada há 4 semanas e evidenciou feto único, cefálico, com índice de líquido amniótico normal, peso fetal no percentil 20 e circunferência abdominal fetal no percentil 30. O Doppler obstétrico apresentou-se normal. Ao exame físico, apresenta-se afebril, eupneica com frequência cardíaca de 88 batimentos por minuto, pressão arterial d e 127 × 66 mmHg. Ao exame físico obstétrico, identifica-se altura uterina de 34 cm, movimentação fetal presente, dinâmica uterina ausente e índice de Bishop de 8. À carditocografia, identificou-se aumento abrupto da frequência cardíaca fetal, com ápice maior ou igual a 15 batimentos por minuto e duração maior ou igual a 15 segundos; batimento cardíaco fetal basal de 130 batimentos por minuto e variabilidade da frequência cardíaca fetal de 20 batimentos por minuto. Nesse caso, conforme o Manual de Gestação de Alto Risco do Ministério da Saúde (2022), qual é a conduta médica adequada?","options":{"A":"Pedir uma ecografia obstétrica com Doppler.","B":"Solicitar a realização de uma amnioscopia.","C":"Indicar a indução de trabalho de parto.","D":"Orientar que retorne em 3 dias."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-032","number":32,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223933","stem":"Uma primigesta, com idade gestacional de 39 semanas, assistida em pré-natal de baixo risco, é admitida no pronto-socorro obstétrico com queixa de “cólica forte que vai e volta”, nega outras queixas. Com intuito de avaliar se a paciente está em trabalho de parto, o médico pede consentimento à gestante para executar o exame físico, informando que precisa realizar, entre outras etapas, a avaliação da dinâmica uterina. Sobre a avaliação da dinâmica uterina, o médico explica para a gestante que o procedimento consiste em colocar a mão espalmada","options":{"A":"no fundo uterino e, a partir da percepção de uma contração, contar o número e duração das contrações em 10 minutos.","B":"na região suprapúbica e, a partir da percepção de uma contração, contar o número e duração das contrações em 10 minutos.","C":"no fundo uterino e, a partir da percepção de uma contração, contar o número e duração das contrações em 5 minutos.","D":"na região suprapúbica e, a partir da percepção de uma contração, contar o número e duração das contrações em 5 minutos."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-033","number":33,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223923","stem":"Uma primigesta de 41 anos, com idade gestacional de 20 semanas, vai à consulta pré-natal para levar seus exames d e rotina, sem apresentar outras queixas. Seu exame físico está normal, os batimentos cardíacos fetais estão em 140 batimentos por minuto e o fundo uterino é de 21 cm. Ao checar os exames, a médica observou que a glicemia de jejum da paciente era de 110 mg/dL. Os demais exames de rotina pré-natal estavam normais. Diante desse quadro, a conduta adequada para essa paciente é","options":{"A":"realizar teste oral de tolerância à glicose com 75 g entre 30 e 34 semanas de gestação, pois ela apresenta pré- diabetes.","B":"realizar teste de glicemia de jejum entre 28 e 30 semanas de gestação, a fim de confirmar o diagnóstico de diabetes gestacional.","C":"iniciar uso de insulina NPH para evitar complicações mais graves para a mãe e para o feto, pois ela apresenta uma alteração na produção de insulina.","D":"iniciar tratamento com dieta pobre em carboidrato e começar a praticar atividade física regular, pois ela apresenta diagnóstico de diabetes gestacional."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-034","number":34,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223918","stem":"Uma primigesta de 38 anos, com idade gestacional de 31 semanas, vai à consulta obstétrica com queixa de cefaleia. A paciente não utiliza medicação nem apresenta histórico de hipertensão arterial. Ao exame, apresentou pressão arterial de 150 × 100 mmHg (realizada em duas verificações, com a paciente em repouso), batimentos cardíacos fetais em 138 batimentos por minuto e altura uterina de 32 cm, trouxe, ainda, resultado de exame de urina de 24 horas que apresentou proteinúria de 350 mg. Nesse caso, a conduta inicial para a paciente deve ser","options":{"A":"internar a paciente para avaliar sinais e sintomas de gravidade.","B":"recomendar dieta hipossódica e, como anti-hipertensivo, o captopril.","C":"prescrever hidralazina em soro fisiológico e nifedipina via oral.","D":"ministrar sulfato de magnésio até a normalização da pressão."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-035","number":35,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223912","stem":"Uma primigesta de 23 anos, com 18 semanas e 4 dias de idade gestacional, procura a unidade básica de saúde apresentando queixa de febre de 38 °C há 1 dia. A febre está associada a exantema maculopapular, prurido, artralgia leve e cefaleia. No município onde a paciente reside, há casos confirmados de dengue, chikungunya e Zika. Acerca desse caso, assinale a alternativa que apresenta a melhor conduta.","options":{"A":"Solicitar sorologias IgM para Zika e para dengue, que, se positivas, confirmam caso de infecção recente por Zika, frente aos sintomas apresentados pela paciente; registrar no cartão da gestante a ocorrência do exantema.","B":"Solicitar RT-PCR para Zika, pois a paciente pertence a grupo prioritário para confirmação laboratorial específica e, se positiva, confirma o caso de infecção por Zika; registrar no cartão da gestante a ocorrência do exantema.","C":"Solicitar RT-PCRs para dengue e chikungunya, que, se negativas, indicam a solicitação de sorologia IgM para dengue; nesse caso, é inadequado realizar o registro do exantema no cartão da gestante, pois o diagnóstico de Zika terá sido descartado.","D":"Solicitar sorologias IgM para Zika e dengue, que, se positivas, confirmam caso de infecção recente por dengue pela possibilidade de reação cruzada; nesse caso, é inadequado realizar o registro do exantema no cartão da gestante, pois o diagnóstico de Zika terá sido descartado."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-036","number":36,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223883","stem":"Uma primigesta de 40 anos, com idade gestacional de 8 semanas, é atendida no pronto-socorro obstétrico com queixa de sangramento transvaginal e de cólicas. Ao exame especular, observa-se saída de moderada quantidade de sangue vivo pelo orifício externo do colo uterino. Ao toque bimanual, o útero apresenta consistência amolecida, volume aumentado e os orifícios externo e interno do colo uterino estão dilatados de 1 para 2 cm. Foi realizada ecografia obstétrica transvaginal q u e mostrou um saco gestacional tópico e regular, contendo, em seu interior, uma vesícula vitelina de aspecto ecográfico normal e um embrião medindo 15 mm de comprimento, com batimentos cardíacos presentes. Nesse caso, o diagnóstico correto é","options":{"A":"aborto retido.","B":"aborto inevitável.","C":"ameaça de aborto.","D":"aborto incompleto."},"answer":"B","explanation":"","needsVisualReview":true},{"id":"obstetricia-inep-037","number":37,"area":"Obstetrícia","source":"INEP","sourceCode":"4000223878","stem":"Uma secundigesta, com história prévia de prematuridade, chega à consulta de pré-natal assintomática, trazendo resultado de ultrassonografia de 22 semanas, o qual revela feto vivo, com exame morfológico normal e com colo uterino medindo 20 mm. Nesse caso, a conduta médica mais adequada é indicar","options":{"A":"realização de cerclagem do colo uterino imediatamente.","B":"nifedipina com início imediato e manter o uso até as 30 semanas de gestação.","C":"betametasona com início imediato e repetir o exame com 30 semanas de gestação.","D":"progesterona natural com início imediato e manter o uso até as 36 semanas gestacionais."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-038","number":38,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218480","stem":"Uma gestante com 24 anos, G2 P1 A0, chega à maternidade com sangramento vermelho vivo por via vaginal. Conta que descobriu sua segunda gravidez há 2 semanas. No momento, refere dor pélvica intensa e persiste com sangramento vaginal vivo. Ao exame, apresenta-se em bom estado geral, normocorada, pressão arterial de 110 x 70 mmHg, frequência cardíaca de 82 bpm e saturação de oxigênio de 98%. No exame físico, o médico plantonista constata colo pérvio no toque bimanual, útero compatível com 10 semanas de gravidez e sangramento vivo com saída de material sugestivo de restos ovulares. Considerando-se essa história clínica e os achados do exame físico, quais são a hipótese diagnóstica e a melhor conduta para a paciente?","options":{"A":"Ameaça de abortamento; solicitar ultrassonografia transvaginal e, se feto com boa vitalidade, recomendar repouso e iniciar pré-natal.","B":"Ameaça de abortamento; prescrever analgésico, recomendar repouso no domicílio e orientar retorno se houver piora do sangramento.","C":"Abortamento em evolução; explicar com linguagem acessível o quadro, internar e realizar ultrassonografia pélvica para confirmar útero vazio.","D":"Abortamento em evolução; explicar com linguagem acessível o quadro, orientando que pode optar por aspiração manual intrauterina (AMIU) / curetagem ou conduta expectante."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-039","number":39,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218470","stem":"Os dados da carteirinha de uma gestante com 28 anos, primigesta, sem intercorrências clínicas prévias à gestação e que foi atendida em uma unidade básica de saúde, estão transcritos a seguir: Com base nesses dados, é correto afirmar que:","options":{"A":"o atendimento pré-natal foi adequadamente realizado.","B":"o diagnóstico de pré-eclâmpsia sem critérios de gravidade pode ser estabelecido.","C":"o referenciamento da paciente para o pré-natal de alto risco não está indicado.","D":"a USG obstétrica morfológica do segundo trimestre foi solicitada no momento incorreto."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-040","number":40,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218465","stem":"Uma paciente com 30 anos, primigesta, comparece ao hospital com gestação de 40 semanas e 4 dias, conforme data da última menstruação (refere ciclos regulares), e de 41 semanas, conforme resultado de ultrassonografia que realizou quando estava com 27 semanas. Ela refere boa movimentação fetal e não apresenta intercorrências clínicas ou obstétricas. Os resultados dos exames de pré-natal são normais. Relata que, apesar de um pouco ansiosa, sente-se tranquila para esperar \"a hora do bebê\". O médico plantonista realiza um exame de cardiotocografia que evidencia uma frequência cardíaca fetal basal de 150 bpm com variabilidade entre 10 e 20 batimentos, duas acelerações transitórias com aproximadamente 15 segundos de duração e que, em seu ápice, chegam a 165 batimentos. Não há desacelerações. É realizado um exame de ultrassonografia, cujo resultado mostra que o feto está cefálico, com líquido amniótico normal. Diante do quadro clínico descrito, assinale a opção correta.","options":{"A":"A paciente deve ser internada para indução, pois a frequência cardíaca fetal evidencia sinais de hipóxia fetal.","B":"A paciente deve ser submetida a cesariana, pois duas acelerações transitórias evidenciam sinais de hipóxia fetal.","C":"A paciente deve ser internada para indução, pois, embora os exames mostrem que há bem-estar fetal, o feto está taquicárdico.","D":"A paciente deve ser orientada a retornar em 3 dias (41 semanas pela data da última menstruação), pois os exames mostram sinais de bem-estar fetal."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-041","number":41,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218460","stem":"Uma paciente secundigesta com 28 anos, idade gestacional de 35 semanas, obesa, não apresenta outras comorbidades prévias. No acompanhamento de pré-natal que realizou na unidade básica de saúde, não houve intercorrências até o momento. Os resultados dos exames de rotina de pré-natal apresentam-se normais, assim como as medidas de pressão arterial anteriores, e a altura uterina é compatível com a idade gestacional. Ela comparece a uma consulta no serviço de pronto atendimento encaminhada pela unidade básica de saúde por aumento da pressão arterial. Nega queixas. Refere estar se alimentando bem e relata que engordou 3 quilos nas últimas duas semanas. A pressão arterial é de 140 x 95 mmHg, confirmada após quinze minutos de repouso. A paciente apresenta edema importante em membros inferiores. A movimentação fetal está presente, os batimentos cardíacos fetais são de 144 bpm, e altura uterina é compatível com idade gestacional. Considerando-se o quadro clínico descrito, quais são, respectivamente, o provável diagnóstico e a conduta adequada?","options":{"A":"Pré-eclâmpsia; internar a paciente para controle pressórico e interromper a gestação se comprovada a maturidade fetal.","B":"Pré-eclâmpsia; solicitar exames e verificar se há a presença de proteinúria significativa e/ou se é acusada a disfunção de órgão-alvo, para confirmar o diagnóstico.","C":"Hipertensão arterial crônica; aguardar a evolução no puerpério e, se ocorrer a normalização dos níveis pressóricos em até 12 semanas pós-parto, o diagnóstico estará confirmado.","D":"Emergência hipertensiva; internar a paciente para prescrição de sulfato de magnésio e anti-hipertensivos de ação rápida e interromper a gestação assim que o quadro clínico for estabilizado"},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-042","number":42,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218455","stem":"Em sua segunda consulta de pré-natal, uma paciente com 36 anos, na 8a semana da gestação, refere fadiga, ganho de peso, queda de cabelos e pele ressecada. Relata que já teve 2 abortamentos e que, atualmente, está na terceira gestação. Traz resultado de exames laboratoriais cujo único achado relevante foi o de TSH de 8,20 mUI/L (valor de referência - VR = 0,4 a 4,5 mUI/L). Em relação à condição clínica descrita, assinale a opção correta.","options":{"A":"A prescrição de metimazol deverá ser iniciada imediatamente, considerando-se a principal hipótese diagnóstica e etiologia dessa situação clínica.","B":"Os níveis elevados de estrógenos da gestação estimulam, em nível hepático, aumento na produção de TBG, o que pode determinar a elevação do TSH.","C":"A presença de TSH elevado se correlaciona a perdas fetais, independentemente de a gestante apresentar bócio, sendo mais grave se o resultado do exame de anti-TPO estiver elevado.","D":"A prescrição de levotiroxina somente deverá se iniciar após as 12 semanas de gestação, pois, se administrada antes, a molécula atravessa a barreira placentária e pode inibir o desenvolvimento embriológico da tireoide fetal."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-043","number":43,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218450","stem":"Uma gestante com 12 semanas de gestação comparece ao centro de saúde para mostrar os exames realizados e apresenta sorologia para toxoplasmose com IGM positiva e IGG negativa. Nesse momento, a conduta adequada é","options":{"A":"iniciar espiramicina e solicitar teste de avidez para toxoplasmose e, se a avidez for alta, considerar infecção recente.","B":"iniciar espiramicina e solicitar teste de avidez para toxoplasmose e, se a avidez for baixa, considerar infecção recente.","C":"iniciar espiramicina e solicitar nova sorologia (IGG e IGM) em três semanas e, se IGG positivar, considerar infecção recente.","D":"não iniciar tratamento e solicitar nova sorologia (IGG e IGM) em seis a oito semanas e, se IGG positivar, iniciar espiramicina."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-044","number":44,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218444","stem":"Uma gestante com 27 anos, G2PC1A0, com idade gestacional de 12 semanas, vai à consulta de pré-natal na unidade básica de saúde para mostrar os resultados dos exames de 1º trimestre, os quais podem ser vistos a seguir. Anti-HIV: não reagente; HBsAg: não reagente; anti-HCV: não reagente; teste treponêmico para sífilis: reagente com VDRL 1/32; toxoplasmose: IgG positivo e IgM negativo; glicemia de jejum: 76 mg/dL; tipagem sanguínea: A-; Hb = 10,5 mg/dL; Urocultura negativa. A paciente relatou para o médico que ainda não havia realizado a ultrassonografia de primeiro trimestre e que não possui sorologias prévias. Seu exame físico apresentou-se sem alterações. Diante dessas informações, assinale a opção que apresenta a conduta médica adequada para o caso dessa gestante.","options":{"A":"Prescrever penicilina benzatina 2,4 milhões UI a cada 7 dias, por 3 semanas, e solicitar VDRL de controle mensalmente; iniciar sulfato ferroso com 4 comprimidos por dia e repetir hemograma em 60 dias; solicitar coombs indireto mensalmente e, se negativo, realizar imunoglobulina anti-D no pós-parto, se recém-nascido Rh+","B":"Prescrever penicilina benzatina 2,4 milhões UI, dose única, e solicitar VDRL de controle trimestralmente; iniciar sulfato ferroso com 4 comprimidos por dia e repetir hemograma no 3º trimestre; solicitar coombs indireto no 2º e 3º trimestres e, se negativo, realizar imunoglobulina anti-D até 72 horas após o parto, se recém-nascido Rh-.","C":"Prescrever penicilina benzatina 2,4 milhões UI a cada 7 dias, por 3 semanas, e solicitar VDRL de controle trimestralmente; iniciar sulfato ferroso com 1 comprimido por dia profilático; solicitar teste de avidez para toxoplasmose IgG; solicitar coombs indireto no 3º trimestre para realizar imunoglobulina anti-D com 28 semanas de gestação","D":"Prescrever penicilina benzatina 2,4 milhões UI a cada 7 dias, por 2 semanas, e solicitar VDRL de controle mensalmente; iniciar sulfato ferroso com 1 comprimido por dia profilático com 20 semanas de gestação; solicitar teste de tolerância à glicose; solicitar coombs indireto mensalmente e, se positivo, realizar imunoglobulina anti-D com 28 semanas de gestação."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-045","number":45,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218435","stem":"Uma gestante com 29 anos, primigesta, havia realizado um exame de urocultura durante o pré-natal, cujo resultado apresentou 1.000 UFC/mL de Streptococcus agalactiae. Ainda durante o pré-natal, não se realizou o rastreio para colonização pelo estreptococo beta hemolítico do grupo B (EGB) por meio de cultura do conteúdo vaginal e retal. A paciente chega ao pronto-socorro obstétrico em trabalho de parto, com 38 semanas de gestação, bolsa íntegra. Nesse caso, em relação à profilaxia intraparto de sepse neonatal por EGB, deve-se","options":{"A":"realizar teste rápido para EGB na gestante e, se positivo, prescrever a profilaxia antibiótica.","B":"adotar conduta expectante, pois não há indicação de profilaxia de sepse neonatal por EGB.","C":"prescrever penicilina G por via endovenosa para a gestante, pois há evidência de colonização pelo EGB.","D":"prescrever ampicilina por via endovenosa para a gestante, se houver ruptura das membranas ovulares durante o trabalho de parto."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-046","number":46,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218415","stem":"Uma secundigesta com parto vaginal anterior e sem comorbidades chega à maternidade em trabalho de parto. Dez minutos após a meia-noite, avaliado o processo de trabalho de parto, constata-se evolução normal. Realizado exame físico na paciente, verifica-se uma apresentação em plano positivo (+2), colo 100% esvaecido, com 8 centímetros de dilatação, bolsa rota. À ausculta de batimentos cardíacos fetais, o médico assistente nota uma queda nos batimentos e, por isso, opta por realizar uma cardiotocografia, cujo resultado é mostrado a seguir. Diante do traçado cardiotocográfico, assinale a opção correta.","options":{"A":"A linha de base está entre 100 e 150 bpm, a variabilidade é aumentada, as desacelerações são do tipo precoce, portanto, a conduta deve ser reanimação intrauterina.","B":"A linha de base está entre 110 e 160 bpm, a variabilidade é moderada, as desacelerações são do tipo tardio, portanto, a conduta deve ser mudança de decúbito materno e hidratação endovenosa.","C":"A linha de base está entre 110 e 160 bpm, a variabilidade é moderada, as desacelerações são do tipo precoce, portanto, a conduta deve ser seguimento do acompanhamento do trabalho de parto e do parto.","D":"A linha de base está entre 100 e 150 bpm, a variabilidade é aumentada, as desacelerações são do tipo variável com características desfavoráveis, portanto, a conduta deve ser administração de oxigênio e estímulo sonoro."},"answer":"C","explanation":"","needsVisualReview":true},{"id":"obstetricia-inep-047","number":47,"area":"Obstetrícia","source":"INEP","sourceCode":"4000218410","stem":"Uma mulher com 25 anos, primigesta, na 39ª semana de gestação, encontra-se na segunda fase do trabalho de parto (colo totalmente dilatado, cabeça fletida, encaixada no plano +2 de De Lee, posição occipto-púbica, proporção cefalopélvica adequada), em bloco obstétrico de uma maternidade do Sistema Único de Saúde, atendida por equipe experiente. A gestante, segundo relatou, havia planejado parto normal em seu pré-natal, mas após uma hora de trabalho de parto, entra em exaustão, e as contrações uterinas vão diminuindo em frequência, mesmo depois de medidas encorajadoras de esforço. Realiza-se anestesia neuroaxial, é administrada ocitocina, sendo realizada amniotomia, que revelou líquido meconial. A cardiotocografia apresenta resultado normal, razão pela qual a equipe médica decide aguardar a progressão do parto, porém, com 2 horas e meia de trabalho de parto, nova cardiotocografia aponta bradicardia, e as contrações não se revelam eficientes para a conclusão do período expulsivo. A partir do caso clínico descrito, qual deve ser a melhor conduta?","options":{"A":"Indicar a realização imediata de parto cesáreo de urgência.","B":"Realizar parto vaginal assistido, com utilização de fórceps de Simpson.","C":"Administrar nova dose de ocitocina, para estimulação da contração uterina.","D":"Aguardar até se completarem três horas de evolução, por se tratar de primípara."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-048","number":48,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203365","stem":"Duas gestantes procuram atendimento na emergência da maternidade: Paciente X, de 17 anos, primigesta; realizou quatro consultas no pré-natal da unidade básica de saúde, onde não foi feita cultura para pesquisa do estreptococo do grupo B (EGB). A paciente comparece à maternidade com perda líquida desde o dia anterior; sem outras queixas. Sua idade gestacional calculada pela ultrassonografia é de 35 semanas e 5 dias e o obstetra confirmou amniorrexe no exame especular. Paciente Y, de 31 anos, tercigesta, com duas cesarianas anteriores; apresenta hipertensão crônica controlada com metildopa 1g/dia. A paciente realizou, no pré-natal de alto risco, cultura para EGB com 36 semanas e o resultado foi negativo. Ela comparece à maternidade sem queixas, pois foi encaminhada pela obstetra para cesariana eletiva com 39 semanas. Com relação aos casos apresentados, é correto afirmar que a antibioticoprofilaxia intraparto com a finalidade de prevenir a doença neonatal de início precoce por estreptococo do grupo B é obrigatória","options":{"A":"apenas na paciente Y, pois, apesar de a cultura realizada para EGB ser negativa, a paciente é multípara e hipertensa.","B":"em ambas as pacientes, pois elas possuem fatores de risco para doença neonatal de início precoce por estreptococo do grupo B.","C":"apenas na paciente X, pois sua idade gestacional é inferior a 37 semanas e houve diagnóstico de rotura prematura de membranas ovulares.","D":"em nenhuma das pacientes, pois ambas não possuem fatores de risco para doença neonatal de início precoce por estreptococo do grupo B."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-049","number":49,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203360","stem":"Uma gestante primigesta de 18 anos, com idade gestacional de 35 semanas, comparece ao pronto-socorro do hospital após ser encaminhada pelo médico da unidade básica de saúde (UBS). A carta de encaminhamento solicita avaliação e conduta, devido ao aumento da pressão arterial da paciente e esclarece que ela estava fazendo pré-natal na UBS sem nenhuma intercorrência até o momento, sem comorbidades previas. A paciente refere estar ansiosa, com dor de cabeça intensa e afirma ganho de peso de 3 Kg na última semana. Relata boa movimentação fetal e nega perdas vaginais de líquido ou de sangue. Apresenta pressão arterial de 140 × 90 mmHg, frequência cardíaca de 90 batimentos por minuto e o restante do exame clínico está normal. A altura uterina é de 33 cm, os batimentos cardíacos fetais estão normais com b o a variabilidade e constata-se dinâmica uterina ausente. A gestante, diante desse quadro, é medicada com analgésicos, mas permanece sem melhora importante e os níveis pressóricos se mantêm de 140 × 90 mmHg. Considerando o quadro clínico apresentado, deve-se","options":{"A":"otimizar analgesia, liberar a paciente para continuidade do pré-natal na UBS e orientar retorno ao pronto-socorro, caso apresente piora dos sintomas.","B":"realizar prescrição de medicação sintomática, solicitar exames complementares de urgência e internar a paciente pela necessidade de interrupção desta gestação.","C":"realizar prescrição de medicação sintomática e metildopa, solicitar exames complementares de urgência e liberar a paciente para seguimento em pré-natal de alto risco.","D":"otimizar a analgesia da paciente e mantê-la em observação para acompanhamento da sintomatologia e dos níveis pressóricos, até exclusão de alterações em seus exames complementares."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-050","number":50,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203355","stem":"Uma paciente de 28 anos, em pós parto imediato (seu terceiro parto vaginal), teve parto a termo rápido e a dequitação da placenta sem intercorrências. A revisão perineal foi realizada e estava normal, sem necessidade de sutura. Entretanto, 30 minutos após o parto, a paciente apresentou-se ansiosa e com queixa de tontura e de falta de ar. Ao exame físico, apresenta palidez e extremidades frias, frequência cardíaca de 120 batimentos por minuto e pressão arterial de 90 × 55 mmHg. O útero apresenta-se amolecido e quatro centímetros acima da cicatriz umbilical. A paciente apresenta sangramento vaginal intenso. Ela já possuía um acesso venoso, por meio do qual foi iniciada a expansão volumétrica com soro fisiológico aquecido. Com relação ao quadro apresentado, assinale a opção correta.","options":{"A":"A administração do ácido tranexâmico deverá ser iniciada e paciente encaminhada para histerectomia.","B":"O uso de ácido tranexâmico por via endovenosa está indicado assim que possível, além de drogas uterotônicas.","C":"A administração de drogas uterotônicas é necessária, mas o ácido tranexâmico não deve ser usado, pela ausência de lacerações de trajeto.","D":"O uso de ácido tranexâmico por via endovenosa pelo menos 1 hora após o início da ocitocina é indicado, sobretudo se não houver resposta às drogas uterotônicas."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-051","number":51,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203345","stem":"Uma paciente primigesta de 25 anos, com 30 semanas de idade gestacional, comparece para a consulta de pré-natal de rotina na unidade básica de saúde apresentando febre, lombalgia e queda do estado geral. Nega sinais e sintomas de infecção de vias aéreas superiores e possui diagnóstico prévio de litíase renal. Ao exame físico, apresenta regular estado geral, acianótica, anictérica, corada e hidratada. Temperatura axilar de 38,5 °C, frequência cardíaca de 98 batimentos por minuto, frequência respiratória de 20 incursões respiratórias por minuto, pressão arterial de 120 × 80 mmHg, abdome gravídico, tônus uterino normal e ausência de contrações. Altura uterina de 29 cm, frequência cardíaca fetal de 158 batimentos por minuto e ausência de edemas em membros inferiores. Diante desses achados na paciente, a conduta médica adequada é","options":{"A":"prescrever antitérmico para a gestante e marcar retorno ambulatorial em 7 dias.","B":"prescrever antiespasmódico para a gestante e referenciá-la para uma avaliação eletiva com o infectologista.","C":"prescrever antitérmico para a gestante e referenciá-la para uma avaliação urgente no pronto-socorro obstétrico.","D":"prescrever antiespasmódico para a gestante e referenciá-la para uma avaliação de urgência no pronto socorro obstétrico."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-052","number":52,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203340","stem":"Paciente de 25 anos, com 34 semanas de gestação, comparece à consulta de pré-natal na unidade básica de saúde. Sua gestação é classificada como de risco habitual e todos os seus exames laboratoriais da rotina do pré-natal estão normais. O médico, então, realiza o exame físico obstétrico, incluindo a altura uterina que mede 31 cm. A palpação obstétrica e a estática fetal estão representadas na Figura 1, enquanto o gráfico da altura uterina para a semana de gestação é apresentado na Figura 2. A partir da análise das informações apresentadas, é correto afirmar que a estática fetal e a medida da altura uterina se encontram com feto longitudinal, e","options":{"A":"cefálico, dorso à direita e altura uterina adequada para a idade gestacional.","B":"córmico, dorso à direita e altura uterina diminuída para a idade gestacional.","C":"córmico, dorso à esquerda e altura uterina diminuída para a idade gestacional.","D":"cefálico, dorso à esquerda e altura uterina adequada para a idade gestacional."},"answer":"D","explanation":"","needsVisualReview":true},{"id":"obstetricia-inep-053","number":53,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203335","stem":"Uma paciente primigesta, de 30 anos, com 24 semanas de gestação, encontra-se internada em uma maternidade para introdução de insulina, devido a diabetes gestacional, a fim de obter melhor controle metabólico. A paciente relata que o bebê tem se mexido menos nas últimas 24 horas. O médico indica a realização de uma cardiotocografia de repouso. Nesse caso, a indicação da cardiotocografia está","options":{"A":"incorreta, pois a cardiotocografia é contraindicada em caso de diabetes gestacional, devido às oscilações metabólicas frequentes.","B":"correta, pois, no caso de diabetes descompensado, a cardiotocografia é o exame de escolha para avaliação precoce da vitalidade fetal.","C":"correta, pois é o primeiro exame a ser solicitado em caso de suspeita de sofrimento fetal decorrente de diabetes, com alta sensibilidade.","D":"incorreta, pois, nessa idade gestacional, pela imaturidade no equilíbrio dos sistemas simpático e parassimpático do feto, é alta a taxa de resultados falso-positivos."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-054","number":54,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203330","stem":"Uma paciente com 34 semanas de gestação, G3P2A0, tabagista, com suspeita de restrição de crescimento fetal, é encaminhada ao pré-natal de alto risco para acompanhamento e avaliação. No caso dessa paciente, para a avaliação de idade gestacional fidedigna, o melhor parâmetro a ser utilizado é","options":{"A":"data da última menstruação, mesmo que a paciente tenha ciclos irregulares.","B":"média biométrica fetal observada no exame morfológico realizado com 22 semanas.","C":"comprimento crânio-nádegas em ultrassonografia realizada até 12 semanas da gestação.","D":"medida do diâmetro biparietal observada em ultrassonografia obstétrica realizada entre 14 e 17 semanas."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-055","number":55,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203325","stem":"Uma paciente primigesta, de 33 anos, com idade gestacional de 29 semanas e 4 dias, está em tratamento para infecção urinária e é admitida em trabalho de parto pré-termo. A paciente relata ser tabagista eventual e frequentar academia 3 vezes por semana com exercícios de Pilates e de hidroginástica desde os 30 anos. Em seu cartão de pré-natal, lê-se: índice de massa corporal de 30,4 kg/m², hemoglobina de 9 g/dL e hematócrito de 32%. A partir das informações coletadas acerca dessa paciente, quais são fatores de risco identificados para trabalho de parto pré-termo?","options":{"A":"Tabagismo e prática de atividade física.","B":"Infecção urinária e idade materna.","C":"Anemia e infecção urinária.","D":"Idade materna e anemia."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-056","number":56,"area":"Obstetrícia","source":"INEP","sourceCode":"4000203320","stem":"Uma paciente de 26 anos, com 39 semanas de gestação, comparece ao pronto-socorro da maternidade queixando-se de perda de líquido claro em abundante quantidade há 2 horas. Ela nega outras queixas e refere movimentação fetal ativa. Pré-natal de risco habitual e sem antecedentes pessoais e familiares. Ao exame físico, a paciente apresenta dinâmica uterina ausente, frequência cardíaca fetal de 140 batimentos por minuto com boa variabilidade, feto cefálico e altura uterina de 34 cm. Ao exame especular, apresenta saída de líquido claro com grumos grandes em moderada quantidade e visualizado colo pérvio 1 polpa digital. Com relação a esse caso clínico é possível afirmar que é","options":{"A":"suficiente observar o quadro clínico e o exame físico para fazer o diagnóstico.","B":"recomendável realizar um ultrassom para avaliar se há diminuição de líquido amniótico para fazer o diagnóstico.","C":"necessário proceder com um teste de pH vaginal ou um teste diagnóstico imunocromático para fazer o diagnóstico.","D":"preciso realizar, ao menos, um teste diagnóstico imunocromático ou avaliação de cristalização do conteúdo vaginal ao microscópio para fazer o diagnóstico."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-057","number":57,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194340","stem":"Uma mulher com 26 anos, foi atendida pela equipe de triagem de uma unidade de saúde da família localizada na área rural de um município de pequeno porte. Em razão de queixa de atraso de alguns dias da menstruação, a paciente realizou um teste rápido de gravidez, que se revelou positivo. O médico que a atende, após anamnese completa e exame clínico, classifica-a como gestante de baixo risco e solicita testes rápidos para hepatite B, sífilis (teste treponêmico) e HIV. Os resultados de todos os exames, exceto o de sífilis, são negativos. A paciente relata que não tem alergia a medicamentos, que nunca teve sífilis nem realizou tratamento medicamentoso para essa doença. O médico solicita que ela compareça com seu parceiro à próxima consulta, para que ele também realize os testes rápidos e decide, então, iniciar, para a paciente, o tratamento para sífilis tardia. Após solicitar todos os exames laboratoriais para o pré-natal de baixo risco e o exame VDRL confirmar a doença, o médico prescreve que seja administrado à paciente, na unidade de saúde, benzilpenicilina benzatina de 1.200.000 Ul (intramuscular), em","options":{"A":"1 dose por semana, durante 3 semanas; o VDRL deverá ser monitorado mensalmente; o indicador de cura é que o VDRL reduza pelo menos 1 diluição em relação ao VDRL constatado no momento do diagnóstico.","B":"2 doses por semana, durante 3 semanas; o VDRL deverá ser monitorado mensalmente; o indicador de cura é que o VDRL reduza pelo menos 2 diluições em relação ao VDRL constatado no momento do diagnóstico.","C":"2 doses por semana, durante 2 semanas; o VDRL deverá ser monitorado no 3°, no 9° e no 12° mês após o diagnóstico; o indicador de cura é que o VDRL reduza pelo menos 1 diluição em relação ao VDRL verificado no momento do diagnóstico.","D":"1 dose por semana, durante 2 semanas; o VDRL deverá ser monitorado no 3°, no 9° e no 12° mês após o diagnóstico; o indicador de cura é que o VDRL reduza pelo menos 2 diluições em relação ao VDRL verificado no momento do diagnóstico."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-058","number":58,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194321","stem":"Uma paciente de 20 anos, primigesta, idade gestacional de 12 semanas, comparece à consulta de pré-natal apresentando lesões em alto relevo e aveludadas na região genital próxima ao clitóris. Relata aparecimento, há 1 semana, de lesões cutâneas papulosas eritêmato-acastanhadas no abdome e nas regiões palmar e plantar. Ela apresenta VDRL positivo. Diante dessas condições, o diagnóstico e o tratamento devem ser, respectivamente,","options":{"A":"sífilis recente primária; iniciar penicilina benzatina 2.400.000 UI (intramuscular) em dose única.","B":"sífilis recente secundária; iniciar penicilina benzatina 2.400.000 UI (intramuscular) em dose única.","C":"sífilis latente tardia; iniciar penicilina benzatina 2.400.000 UI (intramuscular) uma vez por semana, por 3 semanas.","D":"sífilis latente recente; iniciar penicilina benzatina 2.400.000 UI (intramuscular) uma vez por semana, por 3 semanas."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-059","number":59,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194310","stem":"Uma primigesta com 22 anos, dona de casa, comparece à unidade de saúde da família (USF) apresentando os resultados de exames solicitados na primeira consulta de pré-natal, realizada há 3 semanas, ao final do primeiro trimestre de gestação. Permanece sem queixas, refere estar usando regularmente o ácido fólico e o sulfato ferroso prescritos, mas diz estar preocupada com o exame de hepatite B. O médico verifica que a tipagem sanguínea é O+, que os testes rápidos para sífilis, HIV e hepatite C foram não reagentes e que todos os outros exames estão dentro da normalidade, apresentando a gestante, no entanto, AgHBs não reagente, Anti-HBc total não reagente e Anti-HBs reagente. Nesse caso, a interpretação dos últimos exames da paciente e a conduta a ser adotada são, respectivamente,","options":{"A":"resultado compatível com hepatite B aguda; solicitar exames bioquímicos e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","B":"resultado compatível com hepatite B crônica; solicitar exames mais específicos e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","C":"resultado indicativo de suscetibilidade ao vírus da hepatite B; orientar a paciente a iniciar o esquema vacinal e a continuar o acompanhamento pré-natal na USF.","D":"resultado indicativo de imunidade ao vírus da hepatite B; esclarecer a paciente de que não há motivo de preocupação e orientá-la a continuar o acompanhamento pré-natal na USF."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-060","number":60,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194306","stem":"Uma paciente primigesta de 16 anos, com 36 semanas de idade gestacional, procura a unidade básica de saúde apresentando ruptura prematura de membranas ovulares. Encaminhada ao hospital em franco trabalho de parto, é admitida em período expulsivo. O recém-nascido (RN), acolhido pela equipe de neonatologia, tem peso adequado para a idade gestacional e sua avaliação na escala Apgar é de 9/9 no primeiro e quinto minutos. No entanto, após 36 horas do nascimento, o RN apresenta quadro de pneumonia e evolui rapidamente para sepse. Nesse caso, para prevenir a ocorrência da sepse, deveria ter sido realizado durante o pré-natal o rastreio e a quimioprofilaxia de qual agente etiológico?","options":{"A":"Streptococcus β-hemolíticos do grupo B.","B":"Chlamydia trachomatis.","C":"Staphylococcus aureus.","D":"Escherichia coli."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-061","number":61,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194296","stem":"O nascimento prematuro continua sendo a principal causa de mortalidade e morbidade perinatais, sendo responsável por até dois terços das mortes neonatais e por déficits físicos, mentais e do desenvolvimento de longo prazo. Nos últimos trinta anos, os avanços foram significativos nos cuidados neonatais e na redução da mortalidade infantil na prematuridade, porém as morbidades e as consequências em longo prazo permanecem. Acerca dos cuidados gestacionais para evitar a prematuridade, assinale a opção correta.","options":{"A":"As evidências científicas indicam a eficácia de uso de progesterona por toda gestante na prevenção à prematuridade.","B":"As pacientes no estágio 3, conforme a Classificação de Risco de Hobel, devem continuar em acompanhamento ambulatorial.","C":"A infecção urinária é fator de risco para a prematuridade, devendo toda gestante com bacteriúria assintomática ser submetida à antibioticoterapia.","D":"Os bloqueadores de canal de cálcio são medicamentos proibidos na inibição dos trabalhos de parto por causarem hipotensão materna e baixo fluxo placentário."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-062","number":62,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194291","stem":"Uma paciente com 24 anos apresenta sangramento vaginal volumoso no puerpério imediato de parto vaginal sem episiotomia. Relata como antecedentes pré-natal e parto vaginal sem intercorrências ou morbidade associada à gestação. Ao exame físico, apresenta-se: em regular estado geral; confusa; com frequência cardíaca de 138 batimentos por minuto; pressão arterial de 80 × 50 mmHg; à ausculta cardíaca, com ritmo cardíaco regular em dois tempos, bulhas hipofonéticas, sem sopros; à ausculta pulmonar, com murmúrios vesiculares sem ruídos adventícios. O exame do abdome da paciente evidencia útero amolecido e palpável 8 cm acima da cicatriz umbilical. Em análise do partograma, foi constatado uso de ocitocina 05 UI durante as 14 horas de condução do trabalho de parto. Diante do quadro apresentado, a conduta inicial adequada é","options":{"A":"iniciar imediatamente a infusão de Ringer Lactato 1.000 ml em acesso venoso calibroso, realizar massagem uterina e usar drogas uterotônicas.","B":"encaminhar a paciente para a ultrassonografia de urgência e solicitar hemograma, para avaliar necessidade de hemotransfusão.","C":"realizar laparotomia de urgência e histerectomia, com hemotransfusão, sem necessidade de prova cruzada.","D":"tranquilizar a paciente, esclarecendo que se trata de loquiação fisiológica do puerpério imediato."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-063","number":63,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194286","stem":"Uma paciente com 39 semanas e 2 dias de idade gestacional chega à unidade de pronto atendimento para avaliação obstétrica e, após anamnese e exame físico geral, foi constatada, no exame de toque vaginal, uma apresentação fetal como a ilustrada na foto a seguir. Com relação à foto, é correto afirmar que se trata de uma apresentação cefálica","options":{"A":"defletida de 1° grau, bregmática.","B":"defletida de 2° grau, de fronte.","C":"defletida de 3° grau, de face.","D":"fletida, occipital."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-064","number":64,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194281","stem":"Uma paciente com 10 semanas de idade gestacional comparece a consulta para avaliação de resultados dos exames solicitados na rotina do pré-natal. Apresenta exame de glicemia de jejum 91 mg/dL. O teste oral de tolerância à glicose (TOTG) com avaliação da glicemia de jejum, após uma hora e após duas horas, tem os limites para o DMG de 92 mg/dL (jejum), de 180 mg/dL (após uma hora) e de 153 mg/dL (após duas horas). Nesse caso, a conduta recomendada para o rastreamento e para a definição da presença ou não de diabetes gestacional é realizar o TOTG com","options":{"A":"100 g, entre 32 e 36 semanas gestacional, já que o diagnóstico é feito com pelo menos um valor alterado.","B":"75 g, entre 24 e 28 semanas de gestação, visto que o diagnóstico é feito com pelo menos um valor alterado.","C":"75 g, entre 22 e 28 semanas de gestação, pois o diagnóstico é feito com pelo menos dois valores alterados.","D":"100 g, entre 34 e 36 semanas de gestação, uma vez que o diagnóstico é feito com pelo menos dois valores alterados."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-065","number":65,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194276","stem":"Uma paciente com 30 anos, primigesta, tipagem sanguínea B+, sem comorbidades, sem queixas atuais e estável hemodinamicamente, chega a uma unidade ambulatorial com o seguinte resultado de exame feito no mesmo dia: BHCG de 2.500 mUI/ml, e com ecografia mostrando uma massa anexial de 2,0 cm (sem embrião vivo) e ausência de gestação intrauterina. A paciente já havia feito exames há 3 dias que mostraram um BHCG de 1.500 mUI/ml. Considerando-se que essa paciente deseja gestar no futuro, que todos os demais exames laboratoriais estão normais e que ela tem possibilidade de dar seguimento ao tratamento proposto, é melhor","options":{"A":"indicar cirurgia aberta.","B":"adotar conduta expectante.","C":"adotar conduta medicamentosa com metotrexato.","D":"indicar cirurgia videolaparoscópica para salpingoplastia."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-066","number":66,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194271","stem":"Uma paciente com 27 anos, primigesta, com 37 semanas, foi admitida no pronto atendimento com quadro de dor abdominal súbita, sangramento vaginal vermelho vivo de pequena/moderada quantidade. Foi realizado o diagnóstico de descolamento prematuro de placenta e um dos médicos da equipe propôs a realização de amniotomia durante o toque vaginal, pois, ao exame físico, constatou-se que o colo é pérvio para 4 cm e é possível a palpação das membranas com facilidade, e que o bebê está em nível + 1 de plano de apresentação. Com relação à proposta da amniotomia, o médico estava","options":{"A":"incorreto, pois a amniotomia se relaciona a um aumento de risco de embolia amniótica.","B":"correto, pois a amniotomia se relaciona a um menor tempo de dequitação da placenta após o parto.","C":"correto, pois a amniotomia se relaciona a redução do risco de coagulação intravascular disseminada.","D":"incorreto, pois a amniotomia se relaciona a um risco aumentado de piora da zona de descolamento de placenta."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-067","number":67,"area":"Obstetrícia","source":"INEP","sourceCode":"4000194256","stem":"Uma mulher de 19 anos comparece a uma unidade de emergência com dor em fossa ilíaca esquerda há 3 dias, mais intensa neste dia. Nega febre e afirma ter relação sexual heterossexual, utilizando-se de condon como meio de anticoncepção, de forma irregular. Refere que a última menstruação ocorreu há 45 dias. Ao exame físico, apresenta pressão arterial de 90 × 50 mmHg, frequência cardíaca de 110 batimentos por minuto, temperatura axilar de 36,7 oC, abdome doloroso em andar inferior, principalmente em fossa ilíaca esquerda, com descompressão dolorosa. Ao exame especular, nota-se sangramento discreto pelo orifício externo do colo; toque com dor a palpação de região anexial esquerda, útero intrapélvico, colo fechado. Considerando-se o quadro descrito e os dados apresentados, o principal diagnóstico e a conduta adequada são, respectivamente","options":{"A":"gravidez ectópica esquerda; solicitar Beta HCG e ultrassonografia transvaginal.","B":"torção anexial esquerda; solicitar ultrassonografia de abdome total e hemograma.","C":"doença inflamatória pélvica; solicitar hemograma e PCR para pesquisa de clamídia.","D":"cisto roto de ovário esquerdo; solicitar hemograma e tomografia de abdome e pelve."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-068","number":68,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178621","stem":"Adolescente de 14 anos de idade, primípara, em puerpério imediato de parto vaginal, apresenta sangramento vaginal abundante, sem morbidades associadas à gestação. No exame, ela apresentou: regular estado geral, frequência respiratória de 23 incursões por minuto; tempo de enchimento capilar de 6 segundos; frequência cardíaca de 128 batimentos por minuto; pressão arterial de 80 x 30 mmHg; abdome globoso, normotenso; útero contraído abaixo da cicatriz umbilical, sem lesões no canal de parto. Diante do quadro apresentado, assinale a opção que estabelece a conduta apropriada a ser adotada em conjunto com a reanimação.","options":{"A":"Administração de 800 mcg de misoprostol via retal.","B":"Indicação de laparotomia de urgência para histerectomia.","C":"Conduta expectante, mantendo-se a monitorização clínica.","D":"Exame da placenta e, caso estejam presentes escavações, indicação de curetagem uterina."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-069","number":69,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178606","stem":"Paciente de 36 anos, G1P0, idade gestacional de 24 semanas, gravidez não planejada, mas bem aceita, compareceu ao pré-natal de alto risco, para consulta. Tem história de gastroplastia para tratamento de obesidade há 10 meses, técnica de bypass gástrico em Y de Roux (RYGB) — na época, pesava 104 kg e media 1,62 m (IMC = 39). Agora, está com 88 kg (IMC = 33). Segundo ela, às vezes, após o almoço, sente mal-estar e tontura. Considerando as informações anteriores, assinale a opção correta.","options":{"A":"O intervalo mais curto entre a cirurgia e a concepção está associado a maior risco de prematuridade e de parto de recém-nascidos pequenos para a idade gestacional.","B":"O teste oral de tolerância à glicose deverá ser realizado entre a 24ª e a 28ª semana de gestação, pelo risco aumentado de diabetes mellitus gestacional.","C":"A reposição de ferro deverá ser feita por via intravenosa, pelo risco aumentado de anemia ferropriva e megaloblástica.","D":"Para as gestantes com suspeita de dumping, deve-se estimular a ingestão de carboidratos de rápida absorção, pelo risco aumentado de desencadear a síndrome."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-070","number":70,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178600","stem":"Durante o pré-natal de uma primigesta com 18 semanas, o médico da unidade básica de saúde teve acesso ao resultado do VDRL, com titulação de 1:4. A paciente não recordava ter sido diagnosticada com sífilis nem ter feito tratamento contra essa doença. Com base nesse resultado de exame VDRL durante o pré-natal e nos dados da entrevista clínica, assinale a opção correta.","options":{"A":"Considerando o título baixo de VDRL, o médico pode esperar para fazer exames seriados mensais de VDRL antes de instituir tratamento.","B":"Caso a paciente tenha alergia à penicilina, deve-se seguir com a gestação sem tratamento até o momento do parto, quando se deve instituir tratamento com eritromicina.","C":"Após o tratamento com penicilina, a paciente deve repetir o VDRL no último trimestre, realizando novo tratamento caso o resultado seja positivo, independentemente da titulação.","D":"O tratamento de escolha deve ser feito com penicilina G benzatina, 2,4 milhões de unidades, IM, semanalmente, durante 3 semanas."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-071","number":71,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178586","stem":"Secundigesta de 25 anos de idade foi encaminhada para o pré- natal de alto risco, por história de pré-eclâmpsia grave com 32 semanas de gestação, o que havia motivado uma cesariana de urgência na primeira gestação. Durante a anamnese, ela revelou história de trombose venosa profunda em membro inferior esquerdo aos 19 anos de idade, quando descobriu ter deficiência de antitrombina (homozigótica). Haja vista a história apresentada, qual deverá ser a estratégia farmacológica para essa gestação?","options":{"A":"Enoxaparina 40 mg/dia.","B":"Ácido acetilsalicílico 100 mg/dia.","C":"Ácido acetilsalicílico 100 mg/dia + enoxaparina 40 mg/dia.","D":"Ácido acetilsalicílico 100 mg/dia + enoxaparina 1 mg/kg de 12/12h."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-072","number":72,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178571","stem":"Secundigesta de 25 anos de idade procurou a clínica da família para iniciar seu pré-natal na 16ª semana de gestação. Referiu ter tido um parto pré-termo anterior, na 21ª semana de gestação. Trouxe consigo uma ultrassonografia transvaginal, que mostrou colo do útero de 43 mm de comprimento. Qual é a conduta mais efetiva a ser proposta nesse momento, a ;m de reduzir a ocorrência de uma nova perda gestacional nessa paciente?","options":{"A":"Indicação de cerclagem eletiva via transvaginal.","B":"Uso de progesterona natural micronizada 200 mg à noite.","C":"Suplementação diária de ácido fólico associado a ômega 3.","D":"Rastreio de estreptococo do grupo B em cultura vaginal e retal."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-073","number":73,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178560","stem":"Primigesta de 24 anos, vendedora, compareceu a unidade de saúde da família (USF) com os resultados de exames solicitados na primeira consulta de pré-natal, realizada havia quatro semanas, ao final do primeiro trimestre de gestação. Estava com idade gestacional de 16 semanas. Negou queixas e referiu estar em uso regular do ácido fólico e do sulfato ferroso prescritos. Disse estar preocupada com o resultado do exame de toxoplasmose. O médico verificou que a gestante apresentava IgG reagente e IgM não reagente para toxoplasmose. Assinale a opção que indica, respectivamente, o que o exame sugere e a conduta a ser tomada.","options":{"A":"Possivelmente um falso-positivo para toxoplasmose; repetir os exames e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","B":"Compatibilidade com toxoplasmose aguda; iniciar o tratamento específico e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","C":"Toxoplasmose pregressa; tranquilizar a paciente de que não há motivos de preocupação e orientá-la a continuar o acompanhamento habitual no pré-natal na USF.","D":"Suscetibilidade à toxoplasmose; orientar a paciente sobre medidas de prevenção e indicar que ela continue o acompanhamento no pré-natal na USF."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-074","number":74,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178546","stem":"Gestante de 39 anos de idade, com histórico de três cesarianas prévias, irá realizar uma cesariana eletiva por iteratividade, com 39 semanas de gestação. Ao ser internada na maternidade para realizar o procedimento, ela apresentou cultura positiva para Streptococcus beta-hemolítico oriundo de swab vaginal e retal colhido com 36 semanas de gestação. Durante a anamnese, a paciente relatou ser alérgica a penicilina benzatina. Diante das informações apresentadas, qual é a melhor conduta a ser adotada?","options":{"A":"Evitar profilaxia antibiótica.","B":"Usar vancomicina 1 g intravascular.","C":"Empregar ampicilina 2 g intravascular.","D":"Utilizar clindamicina 900 mg intravascular."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-075","number":75,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178536","stem":"Tercigesta, com ambas as gravidezes anteriores acometidas por pré-eclâmpsia, apresenta restrição de crescimento fetal intrauterino por insuficiência placentária. Encontra-se na 35ª semana de gestação, com dopplervelocimetria da artéria umbilical com diástole zero, mas com duto venoso normal. Qual é a conduta obstétrica indicada para essa paciente?","options":{"A":"Cesariana eletiva.","B":"Neuroproteção fetal.","C":"Perfil biofísico fetal a cada 3 dias.","D":"Dopplervelocimetria fetal a cada semana."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-076","number":76,"area":"Obstetrícia","source":"INEP","sourceCode":"4000178526","stem":"Mulher com 20 semanas de gestação foi diagnosticada com sífilis, sendo ela e o parceiro adequadamente tratados com penicilina benzatina. Depois de terminado o tratamento inicial, o controle mensal de cura dessa paciente, na Atenção Primária à Saúde, exige seguimento com","options":{"A":"VDRL.","B":"TPHA.","C":"FTA-ABS.","D":"penicilina procaína."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-077","number":77,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176684","stem":"Uma primigesta com 24 anos de idade comparece à consulta médica de rotina de pré-natal com 38 semanas. Relata dores em cólica associadas à s contrações uterinas. No exame obstétrico, apresentou dinâmica uterina positiva e, após as manobras de Leopold, notou-se o dorso à direita, com polo cefálico na pelve, conforme figura a seguir. MONTENEGRO, B; REZENDE FILHO, C. Obstetrícia. 12. ed. Rio de Janeiro: Guanabara Koogan, 2013. A partir dessas informações, a situação, apresentação e posição do feto são, respectivamente,","options":{"A":"situação cefálica, apresentação longitudinal, variedade de posição occípito-esquerda-posterior.","B":"situação cefálica, apresentação longitudinal, variedade de posição occípito-direita-posterior.","C":"situação longitudinal, apresentação cefálica, variedade de posição occípito-direita-posterior.","D":"situação longitudinal, apresentação cefálica, variedade de posição naso-esquerda-anterior."},"answer":"C","explanation":"","needsVisualReview":true},{"id":"obstetricia-inep-078","number":78,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176664","stem":"Uma paciente com 37 anos de idade, primigesta, em atendimento pré-natal em unidade ambulatorial secundária, apresenta amenorreia de 12 semanas. Tem história de hipertensão arterial crônica e refere uso irregular de captopril. Na consulta médica, apresenta-se sem queixas, com pressão arterial de 150 x 100 mmHg, mantida após 30 minutos de decúbito lateral esquerdo; a proteinúria de fita é negativa. O exame obstétrico está compatível com 12 semanas de gestação. Nesse caso, a conduta adequada em relação à pressão arterial da paciente é","options":{"A":"solicitar internação e administração de hidralazina endovenosa.","B":"orientar o uso regular do captopril e fazer curva pressórica.","C":"orientar dieta hipossódica e iniciar metildopa via oral.","D":"orientar dieta hipossódica e fazer curva pressórica."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-079","number":79,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176654","stem":"Uma paciente secundigesta, com 25 anos de idade, 28 semanas de amenorreia, vem à Unidade Básica de Saúde para receber as vacinas que viu em uma campanha na televisão. Em seu cartão de vacinas consta vacinação contra influenza e administração da dTpa há 2 anos, durante sua primeira gestação. Com relação à vacinação dessa paciente contra influenza e coqueluche, deve-se","options":{"A":"realizar a vacinação contra influenza em dose única imediata e administrar nova dose de dTpa.","B":"administrar nova dose de dTpa, não havendo necessidade de nova vacinação contra influenza.","C":"realizar vacinação contra influenza em 2 doses (imediata e após 30 dias) e administrar nova dose de dTpa.","D":"realizar vacinação contra influenza em dose única imediata, não havendo indicação de nova dose da dTpa."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-080","number":80,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176649","stem":"Uma gestante com 35 anos de idade, gesta: 4, para: 3, aborto: 0 (três partos vaginais anteriores), iniciou pré-natal com 11 semanas, ocasião e m que realizou todos o s exames recomendados e nenhuma anormalidade foi detectada. Com 35 semanas, realizou novos exames, sendo diagnosticado HIV, com carga virai de 2.000 cópias/mL. Nessa mesma idade gestacional, iniciou terapia antirretroviral. Nesse caso, a conduta a ser adotada para essa gestante é","options":{"A":"induzir o parto com misoprostol e/ou ocitocina na 38ª semana e realizar zidovudina endovenosa durante todo o procedimento.","B":"programar parto cesariana para a 38ª semana de gestação e iniciar zidovudina endovenosa pelo menos 3 horas antes do procedimento.","C":"realizar parto cesariana na 40ª semana e prescrever zidovudina injetável para ser administrada 1 hora antes do procedimento.","D":"aguardar início espontâneo do parto vaginal até 40 semanas e usar zidovudina endovenosa durante todo o período do trabalho de parto."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-081","number":81,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176620","stem":"De acordo com o Caderno de Atenção Básica n. 32, publicado pelo Ministério da Saúde, durante a consulta de pré-natal de risco habitual na Unidade Básica de Saúde, quais exames complementares devem ser solicitados no primeiro trimestre da gestação, independente da condição clínica ou social da paciente?","options":{"A":"Hemograma; tipagem sanguínea e fator Rh; glicemia de jejum; testes de rastreamento para sífilis, HIV e citomegalovírus; exame de urina e urocultura.","B":"Hemograma; tipagem sanguínea e fator Rh; teste de tolerância oral à glicose; testes de rastreamento para sífilis, HIV e hepatite B; exame de urina e urocultura.","C":"Hemograma; tipagem sanguínea e fator Rh; glicemia de jejum; testes de rastreamento para sífilis, HIV toxoplasmose e hepatite B; exame de urina e urocultura.","D":"Hemograma; tipagem sanguínea e fator Rh; glicemia de jejum; testes de rastreamento para sífilis, HIV, citomegalovírus e hepatite B e C; exame de urina e urocultura."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-082","number":82,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176615","stem":"O médico de uma Equipe de Saúde da Família foi demandado para atendimento a uma gestante no final do primeiro trimestre de gestação. Na consulta, a gestante informou que havia mudado de cidade e trouxe os resultados de exames que havia feito após consulta de abertura de pré-natal na cidade em que morava. O exame clínico e os resultados de exames complementares estavam dentro da normalidade. Nesse caso, o médico deve recomendar a essa paciente que volte para nova consulta","options":{"A":"mensalmente até a 34ª semana.","B":"mensalmente até a 28ª semana.","C":"quinzenalmente até a 34ª semana.","D":"quinzenalmente até a 28ª semana."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-083","number":83,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176614","stem":"Uma gestante primigesta com 25 anos de idade e com idade gestacional de 20 semanas comparece à consulta no Centro d e Saúde referindo uma lesão em vulva. Relata que, inicialmente, sentiu dor e coceira no local e que, pouco depois, apareceu a lesão, que ainda dói e arde. Nega episódios semelhantes anteriores. Ao exame ginecológico, apresenta lesão em fúrcula vaginal, hiperemiada, com vesículas agrupadas, algumas exulceradas. Considerando esse quadro clínico, assinale a opção que apresenta, respectivamente, a principal hipótese diagnóstica e a conduta correta a ser adotada.","options":{"A":"Sífilis (lesão secundária); deve ser solicitado VDRL e teste treponêmico com urgência para definir conduta.","B":"Sífilis (lesão primária); indicação de tratamento com penicilina benzatina para a mulher e o(s) parceiro(s).","C":"Herpes Genital; deve ser solicitada sorologia (IGG e IGM) e cultura de secreção da lesão e, após coleta, iniciar tratamento com aciclovir.","D":"Herpes Genital; indicação de tratamento com aciclovir e com 36 semanas de gestação deve ser prescrito aciclovir profilático, para diminuir o risco de lesões ativas no momento do parto."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-084","number":84,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176604","stem":"Uma mulher com 38 anos de idade comparece ao pronto atendimento com dor em baixo ventre de forte intensidade há algumas horas. A paciente refere que vinha sentindo um leve incômodo em baixo ventre, mas há algumas horas sente dor de forte intensidade em abdome, mais localizada em baixo ventre. Não tem fatores de melhora e piora ao caminhar. Refere náuseas e um episódio de vômito. Nega febre. Como antecedentes já teve uma doença inflamatória pélvica há alguns anos, tratada com antibióticos. Está casada há 10 anos, não utiliza método anticoncepcional hormonal e não usa preservativo em todas as relações. Tem dois filhos que nasceram de parto normal. Nega patologias clínicas. A data da última menstruação foi há aproximadamente 7 semanas. Ao exame, apresenta regular estado geral, lúcida e contactuante, afebril, descorada (++/++++), com pressão arterial de 100 x 55 mmHg e pulso de 110 batimentos por minuto. Exame cardiopulmonar sem anormalidades. Abdome distendido, doloroso, descompressão brusca presente em fossa ilíaca direita. Ruídos hidro aéreos presentes, mas diminuídos. Exame especular sem sangramento, presença de discreta leucorreia fluida sem sinais de vulvovaginite. Toque vaginal com muita dor, dificultando o exame, mas o útero está de tamanho, forma e consistência normal; sente muita dor à palpação de fundo de saco. Considerando o quadro clínico apresentado, assinale a opção que apresenta, respectivamente, a principal hipótese diagnóstica e a conduta correta a ser realizada.","options":{"A":"Apendicite aguda; cirurgia.","B":"Gestação ectópica rota; cirurgia.","C":"Doença inflamatória pélvica; antibioticoterapia parenteral.","D":"Aborto ou ameaça de aborto; internação para observação."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-085","number":85,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176600","stem":"Primigesta com 36 anos de idade e com 26 semanas de gestação comparece à consulta de rotina de pré-natal na Unidade de Saúde da Família (USF). A paciente nega queixas, apresenta situação vacinai atualizada, sorologias de segundo trimestre negativas e procura checagem do resultado do teste oral de tolerância à glicose, realizado há 1 semana. O resultado da glicemia de jejum de primeiro trimestre foi de 90 mg/dL. O médico de Família e Comunidade identifica, no teste oral de tolerância à glicose, glicemia de jejum de 85 mg/dL e encontra o valor de 192 mg/dL na dosagem após 1 hora de sobrecarga e o de 180 mg/dL na dosagem após 2 horas. Com relação a esse caso, quais são, respectivamente, o diagnóstico e a conduta corretos?","options":{"A":"Diabetes mellitus gestacional não detectado; manter seguimento na rotina de pré-natal de risco habitual na USF.","B":"Diabetes mellitus gestacional; solicitar início, na USF, da insulinoterapia (2,5 UI/Kg/dia) e avaliar glicemia capilar em 15 dias.","C":"Diabetes mellitus gestacional; manter acompanhamento longitudinal na USF e encaminhar a paciente para pré- natal de alto risco.","D":"Diabetes mellitus; suspender acompanhamento do pré-natal de risco habitual na USF e encaminhar a paciente ao pré-natal de alto risco."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"obstetricia-inep-086","number":86,"area":"Obstetrícia","source":"INEP","sourceCode":"4000176594","stem":"Uma paciente com 30 anos de idade, gestante pela 3ª vez, comparece ao centro de saúde para acompanhamento pré- natal. Relata que os outros dois partos foram normais, há 10 e 8 anos, que não houve nenhuma intercorrência nas outras gestações e que não tem nenhuma doença diagnosticada. Refere sintomas típicos de início de gestação: enjoo matinal e sonolência. Está com 13 semanas de gestação e apresenta os resultados dos exames de pré-natal anteriormente solicitados. Entre eles, o resultado da glicemia de jejum mostra 132 mg/dL. Com relação a esse caso, qual é a conduta adequada?","options":{"A":"Encaminhar a gestante para pré-natal de alto risco, já que se trata de diabetes mellitus gestacional.","B":"Encaminhar a gestante para pré-natal de alto risco, já que se trata de diabetes mellitus prévio diagnosticado na gestação","C":"Solicitar um teste de tolerância à glicose oral com 75 g imediatamente para elucidar o diagnóstico e avaliar necessidade de encaminhar a paciente ao ambulatório especializado.","D":"Solicitar um teste de tolerância à glicose oral com 75 g com 26 semanas para elucidar o diagnóstico e avaliar necessidade de encaminhar a paciente ao ambulatório especializado."},"answer":"B","explanation":"","needsVisualReview":false}]);
